-- P46 disposition review/replay protection. No live deletion, provider operation,
-- retention default or application endpoint for asserting completed disposal.
create table app_private.disposition_sources(
 source_key text primary key,category text not null check(category in('operational','finance','restricted','profile','guest','security','privacy','prism','learning','backup')),
 scope_kind text not null check(scope_kind in('term','shared')),key_columns text[]not null,
 query_sql text,structure_hash text not null check(structure_hash~'^[a-f0-9]{64}$'),preserve boolean not null default false,
 check((scope_kind='term')=(query_sql is not null))
);
create table public.disposition_heads(
 term_id uuid primary key references public.terms(id),sequence bigint not null check(sequence between 1 and 9007199254740991),entry_hash text not null check(entry_hash~'^[a-f0-9]{64}$')
);
create table public.disposition_entries(
 term_id uuid not null references public.terms(id),sequence bigint not null check(sequence between 1 and 9007199254740991),
 source_key text not null references app_private.disposition_sources(source_key),target_hash text not null check(target_hash~'^[a-f0-9]{64}$'),
 category text not null check(category in('operational','finance','restricted','profile','guest','security','privacy','prism','learning','backup')),
 action text not null check(action in('erase','redact')),replacement_hash text check(replacement_hash~'^[a-f0-9]{64}$'),
 effective_at timestamptz not null check(isfinite(effective_at)),receipt_hash text not null check(receipt_hash~'^[a-f0-9]{64}$'),
 approved_by uuid not null references public.term_memberships(id),previous_hash text not null check(previous_hash~'^[a-f0-9]{64}$'),entry_hash text not null check(entry_hash~'^[a-f0-9]{64}$'),
 primary key(term_id,sequence),unique(term_id,source_key,target_hash),check((action='erase'and replacement_hash is null)or(action='redact'and replacement_hash is not null))
);
alter table public.disposition_heads enable row level security;alter table public.disposition_heads force row level security;
alter table public.disposition_entries enable row level security;alter table public.disposition_entries force row level security;
revoke all on app_private.disposition_sources,public.disposition_heads,public.disposition_entries from public,anon,authenticated,service_role;
create trigger immutable_disposition_entry before update or delete on public.disposition_entries for each row execute function app_private.request_history_guard();
create function app_private.disposition_structure(p_source text)returns text language sql stable security definer set search_path='' as $$
 select encode(sha256(convert_to(coalesce((select string_agg(a.attname||':'||a.atttypid::regtype::text||':'||a.attnotnull::text,','order by a.attnum)from pg_attribute a where a.attrelid=to_regclass(p_source)and a.attnum>0 and not a.attisdropped),'')||E'\n'||coalesce((select string_agg(k.conname||':'||pg_get_constraintdef(k.oid),','order by k.conname)from pg_constraint k where k.conrelid=to_regclass(p_source)),''),'UTF8')),'hex')
$$;
create function app_private.disposition_key(p_source text,p_parts text[])returns text language sql immutable set search_path='' as $$select encode(sha256(convert_to(p_source||E'\n'||array_to_json(p_parts)::text,'UTF8')),'hex')$$;
create function app_private.disposition_catalog_current()returns boolean language sql stable security definer set search_path='' as $$
 select not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r'and n.nspname in('public','app_private')and not exists(select 1 from app_private.disposition_sources s where s.source_key=n.nspname||'.'||c.relname and s.structure_hash=app_private.disposition_structure(s.source_key)))
$$;
-- GENERATED SOURCE REGISTRY — generated from the current synthetic catalog; review SQL projections before hosting.
-- DISPOSITION RUNTIME
create function app_private.disposition_inventory(p_term uuid)returns table(source_key text,target_hash text,category text,root_id uuid,held boolean,state_hash text)language plpgsql security definer set search_path='' set timezone='UTC' as $$declare s app_private.disposition_sources;begin
 if not app_private.disposition_catalog_current()then raise exception using errcode='55000',message='privacy_disposition_catalog_changed';end if;
 for s in select *from app_private.disposition_sources where scope_kind='term'order by source_key loop
  return query execute 'select $2::text,q.*from('||s.query_sql||')q'using p_term,s.source_key;
 end loop;
end$$;
create function app_private.disposition_entry_hash(p_previous text,p_term uuid,p_sequence bigint,p_source text,p_target text,p_category text,p_action text,p_replacement text,p_at timestamptz,p_receipt text)returns text language sql stable set search_path='' set timezone='UTC' as $$
 select encode(sha256(convert_to(p_previous||E'\n'||array_to_json(array[p_term::text,p_sequence::text,p_source,p_target,p_category,p_action,p_replacement,to_char(p_at,'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),p_receipt])::text,'UTF8')),'hex')
$$;
create function app_private.disposition_term_replay_required(p_term uuid)returns boolean language plpgsql security definer set search_path='' set timezone='UTC' as $$declare e public.disposition_entries;s app_private.disposition_sources;present boolean;state text;previous text:=repeat('0',64);seq bigint:=0;head public.disposition_heads;begin
 select *into head from public.disposition_heads where term_id=p_term;
 if not found then return exists(select 1 from public.disposition_entries where term_id=p_term);end if;
 if not app_private.disposition_catalog_current()then return true;end if;
 for e in select *from public.disposition_entries where term_id=p_term order by sequence loop
  seq:=seq+1;if e.sequence<>seq or e.previous_hash<>previous or e.entry_hash<>app_private.disposition_entry_hash(previous,e.term_id,e.sequence,e.source_key,e.target_hash,e.category,e.action,e.replacement_hash,e.effective_at,e.receipt_hash)then return true;end if;
  previous:=e.entry_hash;select *into s from app_private.disposition_sources where source_key=e.source_key;
  if not found or s.query_sql is null then return true;end if;
  execute 'select exists(select 1 from('||s.query_sql||')q where q.target_hash=$2)'into present using p_term,e.target_hash;
  if present then
   if e.action='erase'then return true;end if;
   execute 'select q.state_hash from('||s.query_sql||')q where q.target_hash=$2 limit 1'into state using p_term,e.target_hash;
   if state is distinct from e.replacement_hash then return true;end if;
  end if;
 end loop;
 return head.sequence<>seq or head.entry_hash<>previous;
end$$;
create function app_private.disposition_replay_required(p_term uuid)returns boolean language plpgsql security definer set search_path='' as $$declare scope uuid;other_scope uuid;e public.disposition_entries;s app_private.disposition_sources;present boolean;state text;begin
 -- A shared profile or attachment can be read through another term. Quarantine
 -- the organization when any of its restored ledgers/data need reconciliation.
 for scope in select x.term_id from(select term_id from public.disposition_heads union select term_id from public.disposition_entries)x join public.terms t on t.id=x.term_id where t.organization_id=(select organization_id from public.terms where id=p_term)loop
  if app_private.disposition_term_replay_required(scope)then return true;end if;
  -- A historical membership/invitation may already have been removed while the
  -- same global profile is restored through a different term. Check every scope
  -- in this organization; do not require the old membership to still exist.
  for e in select *from public.disposition_entries where term_id=scope and source_key in('public.members','public.private_profiles','public.profile_commands','public.guest_contact_profiles')loop
   select *into s from app_private.disposition_sources where source_key=e.source_key;
   for other_scope in select id from public.terms where organization_id=(select organization_id from public.terms where id=p_term)loop
    execute 'select exists(select 1 from('||s.query_sql||')q where q.target_hash=$2)'into present using other_scope,e.target_hash;
    if present then
     if e.action='erase'then return true;end if;
     execute 'select q.state_hash from('||s.query_sql||')q where q.target_hash=$2 limit 1'into state using other_scope,e.target_hash;
     if state is distinct from e.replacement_hash then return true;end if;
    end if;
   end loop;
  end loop;
 end loop;return false;
end$$;
create function app_private.append_disposition(p_term uuid,p_source text,p_target text,p_category text,p_action text,p_replacement text,p_at timestamptz,p_receipt text,p_verifier uuid,p_root uuid)returns jsonb language plpgsql security definer set search_path='' set timezone='UTC' as $$declare s app_private.disposition_sources;e public.disposition_entries;h public.disposition_heads;v public.presentation_versions;present boolean;state text;at_time timestamptz:=date_trunc('milliseconds',p_at);begin
 -- Trusted executor/import interface only. No application/service-role execute.
 -- Receipt custody, actual Storage/copy erasure and verification remain external.
 perform app_private.readiness_lock(p_term);
 select *into s from app_private.disposition_sources where source_key=p_source;
 if not found or s.scope_kind<>'term'or s.preserve or not app_private.disposition_catalog_current()then raise exception using errcode='55000',message='privacy_disposition_catalog_changed';end if;
 if p_target is null or p_target!~'^[a-f0-9]{64}$'or p_receipt is null or p_receipt!~'^[a-f0-9]{64}$'or p_category is null or p_category not in('operational','finance','restricted','profile','guest','security','privacy','prism','learning','backup')or p_action is null or p_action not in('erase','redact')or(p_action='erase'and p_replacement is not null)or(p_action='redact'and(p_replacement is null or p_replacement!~'^[a-f0-9]{64}$'))or p_at is null or not isfinite(p_at)or p_at>statement_timestamp()then raise exception using errcode='22023',message='command_validation_failed';end if;
 if not exists(select 1 from public.term_memberships m join public.members a on a.id=m.member_id and a.account_state='active'where m.id=p_verifier and m.term_id=p_term and m.membership_kind='core'and m.status='active'and m.joined_at<=statement_timestamp()and m.ends_at>statement_timestamp()and a.auth_user_id is distinct from auth.uid())then raise exception using errcode='42501',message='command_permission_denied';end if;
 select pv.*into v from public.presentation_versions pv join public.presentation_controls c on c.work_item_id=pv.control_id and c.kind='retention'and c.term_id=p_term join public.work_items w on w.id=c.work_item_id and w.archived_at is null order by pv.version desc limit 1;
 if not found or not app_private.retention_approved(p_term,v.definition,(select m.id from public.term_memberships m join public.members a on a.id=m.member_id where m.term_id=p_term and a.auth_user_id=v.actor_id))or not exists(select 1 from jsonb_array_elements(v.definition->'rules')r where r->>'category'=p_category and r->>'action'='review_disposal')then raise exception using errcode='55000',message='command_dependency_blocked';end if;
 if app_private.retention_is_held(p_term,p_category,p_root,p_root)then raise exception using errcode='55000',message='privacy_disposition_held';end if;
 if p_source in('public.members','public.private_profiles','public.guest_contact_profiles','public.profile_commands','public.guest_profile_commands')and exists(select 1 from public.legal_holds l join public.terms t on t.id=l.term_id where t.organization_id=(select organization_id from public.terms where id=p_term)and l.released_at is null and(l.category is null or l.category=p_category))then raise exception using errcode='55000',message='privacy_disposition_shared_hold';end if;
 select *into e from public.disposition_entries where term_id=p_term and source_key=p_source and target_hash=p_target;
 if found then
  if e.category<>p_category or e.action<>p_action or e.replacement_hash is distinct from p_replacement or e.effective_at<>at_time or e.receipt_hash<>p_receipt or e.approved_by<>p_verifier then raise exception using errcode='22023',message='command_idempotency_conflict';end if;
  return jsonb_build_object('sequence',e.sequence,'entryHash',e.entry_hash);
 end if;
 execute 'select exists(select 1 from('||s.query_sql||')q where q.target_hash=$2)'into present using p_term,p_target;
 if p_action='erase'and present then raise exception using errcode='55000',message='privacy_disposition_not_erased';end if;
 if p_action='redact'then
  execute 'select q.state_hash from('||s.query_sql||')q where q.target_hash=$2 limit 1'into state using p_term,p_target;
  if not present or state is distinct from p_replacement then raise exception using errcode='55000',message='privacy_disposition_not_redacted';end if;
 end if;
 select *into h from public.disposition_heads where term_id=p_term for update;
 e.term_id:=p_term;e.sequence:=coalesce(h.sequence,0)+1;e.previous_hash:=coalesce(h.entry_hash,repeat('0',64));
 e.entry_hash:=app_private.disposition_entry_hash(e.previous_hash,p_term,e.sequence,p_source,p_target,p_category,p_action,p_replacement,at_time,p_receipt);
 return jsonb_build_object('sequence',e.sequence,'entryHash',e.entry_hash);
end$$;
create function public.read_disposition_review(p_term_id uuid,p_page integer default 1)returns jsonb language plpgsql security definer set search_path='' set timezone='UTC' as $$declare sources jsonb;items jsonb;ledger jsonb;h public.disposition_heads;v_catalog_current boolean;begin
 perform app_private.request_actor(p_term_id);if not app_private.privacy_custodian(p_term_id)then raise exception using errcode='42501',message='command_permission_denied';end if;
 if p_page is null or p_page<1 or p_page>1000000 then raise exception using errcode='22023',message='command_validation_failed';end if;
 perform app_private.readiness_lock(p_term_id);v_catalog_current:=app_private.disposition_catalog_current();
 if v_catalog_current then
  select coalesce(jsonb_agg(jsonb_build_object('source',s.source_key,'category',s.category,'scope',s.scope_kind,'preserve',s.preserve,'count',case when s.scope_kind='shared'then null else coalesce(c.n,0)end,'held',coalesce(c.held,0))order by s.source_key),'[]')into sources from app_private.disposition_sources s left join(select source_key,count(*)n,count(*)filter(where held)held from app_private.disposition_inventory(p_term_id)group by source_key)c on c.source_key=s.source_key;
  select coalesce(jsonb_agg(jsonb_build_object('source',i.source_key,'targetHash',i.target_hash,'category',i.category,'held',i.held,'action',case when i.held then'held'when s.preserve then'retain_ledger'else'review_only'end)order by i.source_key,i.target_hash),'[]')into items from(select *from app_private.disposition_inventory(p_term_id)order by source_key,target_hash limit 50 offset(p_page::bigint-1)*50)i join app_private.disposition_sources s on s.source_key=i.source_key;
 else sources:='[]';items:='[]';end if;
 select *into h from public.disposition_heads where term_id=p_term_id;
 select coalesce(jsonb_agg(jsonb_build_object('termId',e.term_id,'sequence',e.sequence,'source',e.source_key,'targetHash',e.target_hash,'category',e.category,'action',e.action,'replacementHash',e.replacement_hash,'effectiveAt',to_char(e.effective_at,'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'receiptHash',e.receipt_hash,'previousHash',e.previous_hash,'entryHash',e.entry_hash)order by e.sequence),'[]')into ledger from(select *from public.disposition_entries where term_id=p_term_id order by sequence limit 100 offset(p_page::bigint-1)*100)e;
 -- Explicit metadata-only recovery exception: remains usable during quarantine.
 return jsonb_build_object('catalogCurrent',v_catalog_current,'sources',sources,'items',items,'page',p_page,'hasMore',case when v_catalog_current then(select count(*)from app_private.disposition_inventory(p_term_id))>p_page::bigint*50 else false end,
 'head',jsonb_build_object('termId',p_term_id,'sequence',coalesce(h.sequence,0),'entryHash',coalesce(h.entry_hash,repeat('0',64))),'ledger',ledger,'ledgerHasMore',coalesce(h.sequence,0)>p_page::bigint*100,'replayRequired',app_private.disposition_replay_required(p_term_id),'executesDeletion',false,'externalVerified',false,
 'externalSources',jsonb_build_array('Actual Storage bytes and independent object listing','Managed Auth/identity linkage','External/downloaded exports and integration caches','Encrypted backup generations and separate key custody'));
end$$;
-- The earlier wrappers all call this helper before returning payloads. During a
-- stale restore, fail closed for the whole affected term until reconciliation.
do $$begin execute replace(pg_get_functiondef('app_private.record_content_read(text,uuid,uuid,boolean)'::regprocedure),'app_private.record_content_read(','app_private.record_content_read_before_disposition(');end$$;
create or replace function app_private.record_content_read(p_endpoint text,p_term uuid,p_object uuid,p_returned boolean)returns void language plpgsql security definer set search_path='' as $$declare scope uuid:=p_term;begin
 if scope is null and p_object is not null then
  select term_id into scope from public.work_items where id=p_object;
  if scope is null then select w.term_id into scope from public.comments c join public.work_items w on w.id=c.work_item_id where c.id=p_object;end if;
  if scope is null then select term_id into scope from public.request_types where id=p_object;end if;
  if scope is null then select t.term_id into scope from public.configuration_drafts d join public.request_types t on t.id=d.request_type_id where d.id=p_object;end if;
  if scope is null then select term_id into scope from public.presentation_drafts where id=p_object;end if;
  if scope is null then select term_id into scope from public.handoffs where id=p_object;end if;
  if scope is null then select term_id into scope from public.synergy_agreements where id=p_object;end if;
  if scope is null then select term_id into scope from app_private.task_import_sessions where id=p_object;end if;
  if scope is null then select term_id into scope from app_private.roster_import_sessions where id=p_object;end if;
 end if;
 if scope is not null and p_endpoint not in('read_retention_review')and app_private.disposition_replay_required(scope)then raise exception using errcode='55000',message='privacy_restore_replay_required';end if;
 perform app_private.record_content_read_before_disposition(p_endpoint,scope,p_object,p_returned);
end$$;
revoke all on function app_private.disposition_structure(text),app_private.disposition_key(text,text[]),app_private.disposition_catalog_current(),app_private.disposition_inventory(uuid),app_private.disposition_entry_hash(text,uuid,bigint,text,text,text,text,text,timestamptz,text),app_private.disposition_term_replay_required(uuid),app_private.disposition_replay_required(uuid),app_private.append_disposition(uuid,text,text,text,text,text,timestamptz,text,uuid,uuid),app_private.record_content_read_before_disposition(text,uuid,uuid,boolean),app_private.record_content_read(text,uuid,uuid,boolean),public.read_disposition_review(uuid,integer)from public,anon,authenticated,service_role;
grant execute on function public.read_disposition_review(uuid,integer)to authenticated;
